import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Capability roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"sdlc/roadmap.md","filePath":"sdlc/roadmap.md","lastUpdated":1793135521000}'),r={name:"sdlc/roadmap.md"};function n(s,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="capability-roadmap" tabindex="-1">Capability roadmap <a class="header-anchor" href="#capability-roadmap" aria-label="Permalink to &quot;Capability roadmap&quot;">​</a></h1><p>Neottia ships the SDLC as bounded slices. This page states what each capability is today: available, experimental, planned, or rejected by default. Epic <a href="https://github.com/dragoscirjan/neottia/issues/162" target="_blank" rel="noreferrer">#162</a> tracks the post-MVP decomposition and reviews every deferred workstream against real first-use evidence.</p><h2 id="status-meanings" tabindex="-1">Status meanings <a class="header-anchor" href="#status-meanings" aria-label="Permalink to &quot;Status meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Available</td><td>Ships in releases today and is covered by deterministic acceptance tests.</td></tr><tr><td>Experimental</td><td>Installable today, but not yet covered by full lifecycle boundaries or first-user evidence.</td></tr><tr><td>Planned</td><td>Accepted for future work with a tracking issue; not installable through the supported surface yet.</td></tr><tr><td>Rejected by default</td><td>Exists only behind a separate reviewed design and an explicit approval contract.</td></tr></tbody></table><h2 id="available" tabindex="-1">Available <a class="header-anchor" href="#available" aria-label="Permalink to &quot;Available&quot;">​</a></h2><ul><li><strong>Project initialization</strong> — <code>neottia init</code> writes the minimal project configuration for Pi, OpenCode, and Claude Code with the <code>local</code> preset. See <a href="/projects/neottia/get-started/configuration">shared configuration</a>.</li><li><strong>Lifecycle installation</strong> — <code>neottia plan --manifest manifest.json</code>, the config-driven <code>neottia sdlc plan</code>, and <code>neottia apply</code> compile and install the seven commands, the operating-protocol skill, and exact runtime package entries; <code>neottia doctor</code> reports gaps without changing anything.</li><li><strong>Receipt-driven updates and uninstall</strong> — plans are digest-protected, repeated installs are idempotent, and uninstall removes only receipt-owned files and host-configuration entries.</li><li><strong>Filesystem Issues and Design Docs</strong> — enabled by initialization; canonical records live under <code>.neottia/issues/</code> and <code>.neottia/design-docs/</code>.</li><li><strong>Local Git source control</strong> — commits stay scoped and reviewable; push, pull requests, and merges require explicit authorization.</li><li><strong>Memory lifecycle capability</strong> — <code>neottia init --enable memory</code> (or <code>capabilities.memory.provider</code>) wires durable memory into every compiled command with read-only retrieval, checkpoint-evidence, and shutdown boundaries; disabled by default. See <a href="/projects/neottia/get-started/configuration">shared configuration</a> and <a href="/projects/neottia/sdlc/">the Memory capability</a>.</li><li><strong>Searchable lifecycle capability</strong> — <code>neottia init --enable searchable</code> (or <code>capabilities.searchable.provider: web</code>) wires bounded web retrieval into every compiled command with stash-backed citations and explicit local-Ollama boundaries; disabled by default. See <a href="/projects/neottia/get-started/configuration">shared configuration</a> and <a href="/projects/neottia/sdlc/">the Searchable capability</a>.</li><li><strong>Claude Code distribution</strong> — project installation writes commands, the operating-protocol skill, optional role agents, and exact generic MCP package entries to <code>.mcp.json</code>. Claude Code requires interactive approval for project MCP servers. Global runtime MCP activation is unsupported.</li><li><strong>Global-scope installation</strong> — available through explicit <code>scope: global</code> targets in the project configuration or the <code>neottia apply --scope global</code> override; project scope remains the default. Claude Code global assets are available only when the lifecycle has no runtime modules.</li></ul><h2 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h2><p>No modules are currently experimental: Memory and Searchable both ship full lifecycle capability boundaries (see Available). The Searchable module keeps its own web-provider and Ollama configuration contract; the SDLC path adds no credential handling.</p><h2 id="planned" tabindex="-1">Planned <a class="header-anchor" href="#planned" aria-label="Permalink to &quot;Planned&quot;">​</a></h2><p>Accepted workstreams with tracking issues; each becomes independently releasable with its own Changesets and documentation.</p><ul><li><strong>Remote provider setup and diagnostics</strong> — first-run configuration for remote Issues, Documents, and source-control providers, with configuration references, runtime installation, credentials, and authentication kept separate. Deferred pending first-user evidence (<a href="https://github.com/dragoscirjan/neottia/issues/162" target="_blank" rel="noreferrer">#162</a>).</li><li><strong>Generic MCP configuration journeys</strong> — installation and configuration guidance for hosts without native MCP support. Same separation requirements apply.</li><li><strong>Interactive configuration wizard</strong> — built on top of the deterministic initializer; discovery and recommendations never silently select credentials or mutation routes.</li><li><strong>Runtime orchestration evaluations</strong> — durable runtime state, model-tier routing and retries, managed Git worktrees, and grouped <code>/work</code> dispatch aliases are evaluated separately and only with explicit cost and authority boundaries.</li><li><strong>Additional harnesses</strong> — Codex, Kiro, GitHub Copilot CLI, and Visual Studio Code Copilot remain deferred under <a href="https://github.com/dragoscirjan/neottia/issues/119" target="_blank" rel="noreferrer">#119</a>.</li></ul><h2 id="rejected-by-default" tabindex="-1">Rejected by default <a class="header-anchor" href="#rejected-by-default" aria-label="Permalink to &quot;Rejected by default&quot;">​</a></h2><ul><li><strong>Autonomous merge, deployment, publication, remote closure, and destructive actions.</strong> The compiled Release contract stops before every irreversible action and requires fresh, action-specific approval. No roadmap item grants authority for these actions; a future implementation requires a dedicated reviewed story, explicit user-authorization contracts, and rollback and monitoring evidence.</li></ul>',13)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
